with base as (select * from web_events where duration_sec between 389 and 392 and session_id in (2, 13, 29, 30) and duration_sec is not null), agg as (select case when duration_sec >= 429 then 'high' when duration_sec >= 174 then 'mid' else 'low' end duration_sec_bucket, count(distinct duration_sec) unique_event_types, avg(duration_sec) avg_duration_sec from base group by case when duration_sec >= 429 then 'high' when duration_sec >= 174 then 'mid' else 'low' end) select duration_sec_bucket, unique_event_types from agg where avg_duration_sec < 420 order by unique_event_types desc
